// Promise 基础：把“获取用户 -> 获取订单 -> 获取物流”串成一条链；每个 then 都接收上一步成功的结果，因此下一步不需要手动嵌套回调。
fetchUser(id)
  .then(user => fetchOrders(user.id)) // 先拿到用户，再用用户 ID 查询订单。
  .then(orders => fetchShipment(orders[0].id)) // 取第一笔订单的物流信息，返回值继续交给下一个 then。
  .then(ship => console.log('包裹状态:', ship.status)) // 所有请求成功后输出最终状态。
  .catch(err => console.error('出错了:', err)); // 任一步失败都会汇聚到这里，避免每层都重复写错误处理。

// Promise.all：当多个异步任务彼此独立时并行等待；只有全部完成后，解构出的 user 和 config 才会同时可用。
const [user, config] = await Promise.all([
  fetchUser(id),
  fetchConfig()
]);

